WITH latest_rows AS (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14'), volume_rank AS (SELECT mktcode,tgtcode,ROW_NUMBER() OVER(ORDER BY volume DESC,mktcode,tgtcode) AS r0 FROM latest_rows), turnover_rank AS (SELECT mktcode,tgtcode,ROW_NUMBER() OVER(ORDER BY turnover DESC,mktcode,tgtcode) AS r1 FROM latest_rows) SELECT a.mktcode,a.tgtcode,a.bizdate FROM latest_rows a JOIN volume_rank v ON v.mktcode=a.mktcode AND v.tgtcode=a.tgtcode JOIN turnover_rank t ON t.mktcode=a.mktcode AND t.tgtcode=a.tgtcode WHERE v.r0/NULLIF(t.r1,0)<=1;
